const crypto = require('crypto');
const body = $json.body || {};
const email = String(body.email || '').trim().toLowerCase();
const subject = String(body.subject || '').trim();
const description = String(body.description || '').trim();
const correlationId = crypto.randomUUID();
const validEmail = /^\S+@\S+\.\S+$/.test(email);
const error = !validEmail ? 'invalid_email' : !subject ? 'empty_subject' : !description ? 'empty_description' : subject.length > 200 || description.length > 10000 ? 'content_too_long' : null;
if (error) return [{ json: { accepted: false, statusCode: 400, error, correlationId } }];
const providedKey = String($json.headers?.['idempotency-key'] || '');
const idempotencyKey = crypto.createHash('sha256').update([email, subject, description, providedKey].join('|')).digest('hex');
return [{ json: { accepted: true, statusCode: 202, correlationId, idempotencyKey, receivedAt: new Date().toISOString(), ticket: { email, subject, description } } }];

const intake = $('Validate and Normalize').first().json;
if (!intake.accepted) throw new Error('unexpected_unaccepted_ticket');
return [{json:{ticket:intake.ticket,correlationId:intake.correlationId,idempotencyKey:intake.idempotencyKey,receivedAt:intake.receivedAt}}];

const input = $json;
const ticket = input.ticket || input;
if (!ticket.email || !ticket.subject || !ticket.description || !input.correlationId || !input.idempotencyKey) throw new Error('invalid_classification_input');
const format = {type:'object',properties:{category:{type:'string',enum:['account','billing','technical','security','feature_request','general','unknown']},priority:{type:'string',enum:['P1','P2','P3','P4']},summary:{type:'string',minLength:1,maxLength:280},sentiment:{type:'string',enum:['positive','neutral','negative','angry','abusive','unknown']},assigned_queue:{type:'string',enum:['security_response','technical_support','account_support','billing_support','product_feedback','general_support','manual_review']},confidence:{type:'number',minimum:0,maximum:1},needs_human_review:{type:'boolean'},reason:{type:'string',minLength:1,maxLength:500},safety_or_security_concern:{type:'string',enum:['none','pii_or_secret','account_takeover','security_incident','self_harm_or_threat','unknown']}},required:['category','priority','summary','sentiment','assigned_queue','confidence','needs_human_review','reason','safety_or_security_concern'],additionalProperties:false};
const prompt = `Return JSON matching the supplied schema. Subject: ${ticket.subject}; Description: ${ticket.description}`;
return [{json:{ticket,correlationId:input.correlationId,idempotencyKey:input.idempotencyKey,receivedAt:input.receivedAt || new Date().toISOString(),ollamaRequest:{model:'llama3.2:3b',prompt,stream:false,format,options:{temperature:0}}}}];

const context = $('Build Fixed Prompt').first().json;
let output;
try { output = JSON.parse($json.response); } catch { throw new Error('invalid_model_json'); }
const categories = ['account','billing','technical','security','feature_request','general','unknown'];
const priorities = ['P1','P2','P3','P4'];
const queues = ['security_response','technical_support','account_support','billing_support','product_feedback','general_support','manual_review'];
const sentiments = ['positive','neutral','negative','angry','abusive','unknown'];
const concerns = ['none','pii_or_secret','account_takeover','security_incident','self_harm_or_threat','unknown'];
for (const key of ['category','priority','summary','sentiment','assigned_queue','confidence','needs_human_review','reason','safety_or_security_concern']) if (!(key in output)) throw new Error('missing_model_field_' + key);
if (!categories.includes(output.category) || !priorities.includes(output.priority) || !queues.includes(output.assigned_queue) || !sentiments.includes(output.sentiment) || !concerns.includes(output.safety_or_security_concern)) throw new Error('invalid_model_enum');
if (typeof output.confidence !== 'number' || !Number.isFinite(output.confidence) || output.confidence < 0 || output.confidence > 1) throw new Error('invalid_model_confidence');
if (typeof output.needs_human_review !== 'boolean') throw new Error('invalid_model_review_flag');
if (!String(output.summary).trim() || String(output.summary).length > 280 || !String(output.reason).trim() || String(output.reason).length > 500) throw new Error('invalid_model_text');
return [{json:{ticket:context.ticket,correlationId:context.correlationId,idempotencyKey:context.idempotencyKey,receivedAt:context.receivedAt,classification:output,modelLatencyMs:$json.total_duration ? Math.round($json.total_duration / 1000000) : null}}];

const context = $('Build Fixed Prompt').first().json;
const message = String($json.error?.message || $json.message || 'classification_failed');
const known = ['invalid_model_json','invalid_model_enum','invalid_model_confidence','invalid_model_review_flag','invalid_model_text'];
const errorCode = known.find(code => message.includes(code)) || (message.includes('missing_model_field_') ? 'missing_model_field' : 'ollama_or_classification_failed');
const humanReview = errorCode !== 'ollama_or_classification_failed';
return [{json:{stage:'classification',failureClass:humanReview ? 'human_review' : 'retryable',errorCode,idempotencyKey:context.idempotencyKey,sourceWorkflow:'helpdesk-ai-classification'}}];

const input = $json;
const ticket = input.ticket || {};
const c = input.classification || {};
const allowedCategories = ['account','billing','technical','security','feature_request','general','unknown'];
const allowedQueues = ['security_response','technical_support','account_support','billing_support','product_feedback','general_support','manual_review'];
const allowedPriorities = ['P1','P2','P3','P4'];
if (!ticket.email || !ticket.subject || !ticket.description || !input.correlationId || !input.idempotencyKey) throw new Error('invalid_routing_input');
if (!allowedCategories.includes(c.category) || !allowedPriorities.includes(c.priority) || !allowedQueues.includes(c.assigned_queue) || typeof c.confidence !== 'number' || c.confidence < 0 || c.confidence > 1) throw new Error('invalid_classification_contract');
const text = (ticket.subject + ' ' + ticket.description).toLowerCase();
const security = c.category === 'security' || /account takeover|compromis|security incident|credential/.test(text) || ['account_takeover','security_incident'].includes(c.safety_or_security_concern);
const outage = /outage|service down|all users|production down/.test(text);
const review = security || outage || c.confidence < 0.80 || c.needs_human_review === true || c.category === 'unknown' || c.safety_or_security_concern !== 'none';
let priority = security ? 'P1' : outage ? 'P2' : c.priority;
if ((c.category === 'account' || c.category === 'technical') && priority === 'P4') priority = 'P3';
const queue = security ? 'security_response' : review ? 'manual_review' : c.assigned_queue;
const received = new Date(input.receivedAt || Date.now());
if (Number.isNaN(received.getTime())) throw new Error('invalid_received_at');
const minutes = {P1:240,P2:480,P3:960,P4:2400}[priority];
function businessDeadline(at, remaining) {
  while (remaining > 0) {
    const day = at.getUTCDay(), hour = at.getUTCHours();
    if (day === 6) { at.setUTCDate(at.getUTCDate()+2); at.setUTCHours(1,0,0,0); continue; }
    if (day === 0) { at.setUTCDate(at.getUTCDate()+1); at.setUTCHours(1,0,0,0); continue; }
    if (hour < 1) { at.setUTCHours(1,0,0,0); continue; }
    if (hour >= 9) { at.setUTCDate(at.getUTCDate()+1); at.setUTCHours(1,0,0,0); continue; }
    const used = Math.min(remaining, (9-hour)*60-at.getUTCMinutes());
    at = new Date(at.getTime()+used*60000); remaining -= used;
  }
  return at;
}
const deadline = priority === 'P1' ? new Date(received.getTime()+minutes*60000) : businessDeadline(received, minutes);
return [{json:{correlationId:input.correlationId,idempotencyKey:input.idempotencyKey,ticket,classification:{...c,priority,assigned_queue:queue,needs_human_review:review},status:review?'manual_review':'routed',slaDeadline:deadline.toISOString(),modelLatencyMs:input.modelLatencyMs || null}}];

const body = $json.body || $json;
const reviewTaskId = String(body.reviewTaskId || '').trim();
const reviewer = String(body.reviewer || '').trim();
const decision = String(body.decision || '').trim();
const assignedQueue = String(body.assignedQueue || '').trim();
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const queues = ['security_response','technical_support','account_support','billing_support','product_feedback','general_support'];
if (!uuid.test(reviewTaskId)) throw new Error('invalid_review_task_id');
if (!reviewer || reviewer.length > 120) throw new Error('invalid_reviewer');
if (!['route','reject'].includes(decision)) throw new Error('invalid_review_decision');
if (decision === 'route' && !queues.includes(assignedQueue)) throw new Error('invalid_assigned_queue');
return [{json:{reviewTaskId,reviewer,decision,assignedQueue:decision === 'route' ? assignedQueue : 'manual_review'}}];

const input = $json || {};
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const key = /^[a-f0-9]{64}$/i;
const stage = ['classification','routing','notification'].includes(input.stage) ? input.stage : 'unknown';
const failureClass = ['retryable','non_retryable','human_review','terminal'].includes(input.failureClass) ? input.failureClass : 'terminal';
const errorCode = String(input.errorCode || 'workflow_stage_failed').replace(/[^a-z0-9_]/gi, '_').slice(0, 80) || 'workflow_stage_failed';
const ticketId = uuid.test(String(input.ticketId || '')) ? String(input.ticketId) : null;
const idempotencyKey = key.test(String(input.idempotencyKey || '')) ? String(input.idempotencyKey).toLowerCase() : null;
const sourceWorkflow = String(input.sourceWorkflow || '').replace(/[^a-z0-9:_-]/gi, '_').slice(0, 120);
const sourceExecutionId = String(input.sourceExecutionId || '').replace(/[^a-z0-9:_-]/gi, '_').slice(0, 120);
const replayable = Boolean(idempotencyKey) && ['classification','routing','notification'].includes(stage) && failureClass === 'retryable';
const replayContext = replayable ? {version:1,stage,idempotency_key:idempotencyKey,source_workflow:sourceWorkflow || undefined,source_execution_id:sourceExecutionId || undefined} : {version:1,stage,replayable:false};
return [{json:{ticketId,stage,failureClass:replayable ? 'retryable' : 'terminal',errorCode,idempotencyKey,replayContext,nextRetryAt:replayable ? new Date(Date.now() + 30000).toISOString() : null}}];

const body = $json.body || $json;
const failedJobId = String(body.failedJobId || '').trim();
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (!uuid.test(failedJobId)) throw new Error('invalid_failed_job_id');
return [{json:{failedJobId}}];

const ticket = $json;
const job = $('Claim Failed Job Atomically').first().json;
if (!ticket.ticket_id || !ticket.correlation_id || !ticket.idempotency_key) throw new Error('replay_ticket_not_found');
return [{json:{ticket:{email:ticket.requester_email,subject:ticket.subject,description:ticket.description},correlationId:ticket.correlation_id,idempotencyKey:ticket.idempotency_key,receivedAt:ticket.created_at,failedJobId:job.failed_job_id}}];
